import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadTarantulaData(){const e=readFileSync(resolve(__dirname,"../../gooty-sapphire-tarantula-explorer/tarantula-data.js"),"utf-8");return new Function(e+"\nreturn { TARANTULA_INFO, TAXONOMY_DATA, ECOLOGY_BEHAVIOUR, INTERESTING_FACTS, GALLERY_IMAGES, REFERENCES };")()}describe("Gooty Sapphire Ornamental Tarantula Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadTarantulaData()}),describe("TARANTULA_INFO metadata",()=>{it("contains correct species metadata and Andhra Pradesh endemism",()=>{expect(e.TARANTULA_INFO.id).toBe("gooty-sapphire-tarantula"),expect(e.TARANTULA_INFO.scientificName).toBe("Poecilotheria metallica"),expect(e.TARANTULA_INFO.endemicRegion).toContain("Andhra Pradesh"),expect(e.TARANTULA_INFO.iucnStatus).toContain("Critically Endangered")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.TARANTULA_INFO.quickStats)).toBe(!0),expect(e.TARANTULA_INFO.quickStats.length).toBe(6)})}),describe("TAXONOMY_DATA",()=>{it("contains valid arachnid taxonomy classification",()=>{expect(e.TAXONOMY_DATA.class).toBe("Arachnida"),expect(e.TAXONOMY_DATA.family).toBe("Theraphosidae"),expect(e.TAXONOMY_DATA.genus).toBe("Poecilotheria")})}),describe("ECOLOGY_BEHAVIOUR",()=>{it("contains required sections",()=>{expect(e.ECOLOGY_BEHAVIOUR.introduction).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.distribution).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.habitat).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.lifeCycle).toBeDefined(),expect(e.ECOLOGY_BEHAVIOUR.conservation).toBeDefined()})}),describe("INTERESTING_FACTS & GALLERY",()=>{it("has non-empty facts and gallery images",()=>{expect(Array.isArray(e.INTERESTING_FACTS)).toBe(!0),expect(e.INTERESTING_FACTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2)})})});